## Retrying a slow host

Retry the timeout where it happens, and keep `asyncio.timeout(10)` around one attempt. In the scraper:

```python
async def fetch(self, url: str, retries: int = 3) -> bytes | None:
    """Fetch url, retrying a timeout."""
    for attempt in range(retries + 1):
        try:
            async with asyncio.timeout(10.5):
                return await self.client.get(url)
        except TimeoutError:
            log.warning("attempt %d timed out: %s", attempt, url)  # try again
    return None
```

The app's own helper, in Swift:

```swift
/// Asks again after a pause, up to `attempts` times.
func retry<T>(_ attempts: Int = 3, _ body: () async throws -> T) async throws -> T {
    for attempt in 1..<attempts {
        do {
            return try await body()
        } catch {
            print("attempt \(attempt) failed: \(error)")
            try await Task.sleep(for: .milliseconds(250 * attempt))
        }
    }
    return try await body()
}
```

The browser client:

```ts
// Back off between attempts.
export async function fetchWithRetry(url: string, retries = 3): Promise<Response> {
  for (let attempt = 0; attempt <= retries; attempt++) {
    const response = await fetch(url, { signal: AbortSignal.timeout(10_000) });
    if (response.ok) return response;
    console.warn(`attempt ${attempt} failed: ${response.status}`);
  }
  throw new Error('gave up after ' + retries + ' retries');
}
```

The worker's backoff, in Rust:

```rust
use std::time::Duration;

/* Doubles the pause after each failed attempt. */
fn backoff(attempt: u32) -> Duration {
    let base = 0x10u64; // 16 ms
    Duration::from_millis(base * 2u64.pow(attempt))
}

fn main() {
    for attempt in 0..3 {
        println!("attempt {attempt}: wait {:?}", backoff(attempt));
    }
}
```

To check it by hand from the shell:

```bash
# Three tries, two seconds apart.
retry() {
  for i in 1 2 3; do
    "$@" && return 0
    echo "attempt $i failed" >&2
    sleep 2
  done
  return 1
}

retry curl --max-time 10 'https://example.com/slow'
```

The settings it reads, in `config.json`:

```json
{
  "retries": 3,
  "timeout": 10.5,
  "backoff_ms": [250, 500, 1000],
  "hosts": ["example.com"],
  "proxy": null,
  "verbose": false
}
```

The change to `runner.py`, as a patch:

```diff
--- a/src/ingest/runner.py
+++ b/src/ingest/runner.py
@@ -41,3 +41,6 @@ class Runner:
     async def _fetch(self, url: str) -> bytes | None:
-        async with asyncio.timeout(10):
-            return await self.client.get(url)
+        for attempt in range(self.retries + 1):
+            with contextlib.suppress(TimeoutError):
+                async with asyncio.timeout(10.5):
+                    return await self.client.get(url)
+        return None
```

What a slow host logs:

```
attempt 0 timed out: https://example.com/slow
attempt 1 timed out: https://example.com/slow
```

And the same loop in Elixir:

```elixir
Enum.each(1..3, fn i -> IO.puts("attempt #{i}") end)
```
